import fs from 'node:fs';
import crypto from 'node:crypto';
import { createRequire } from 'node:module';
import path from 'node:path';
import { defineConfig, type Plugin } from 'vite';
import { offloadSkillManifest } from './src/main/orch/skill-manifest-offload';

const require = createRequire(import.meta.url);

const GENERATED_SKILL_MANIFEST = /[\\/]src[\\/]main[\\/]orch[\\/][a-z0-9-]+-manifest\.ts$/u;

/**
 * The skill manifests generated by scripts/bundle-skills.mjs keep every asset
 * as a string literal, and impeccable ships a 17 MB base64 binary. Inside the
 * Main bundle that meant ~50 MB of V8 heap for the life of the process and a
 * ~300 MB RSS spike while parsing it at boot. Large assets leave the bundle as
 * a JSON payload next to the chunks (inside app.asar) that is read only when a
 * file has to be written — see src/main/orch/skill-manifest-offload.ts.
 */
function offloadBundledSkillAssets(): Plugin {
  return {
    name: 'nexus:offload-bundled-skill-assets',
    load(id) {
      const file = id.split('?')[0]!;
      if (!GENERATED_SKILL_MANIFEST.test(file)) return null;
      const fileName = `skills/${path.basename(file, '.ts')}.json`;
      const result = offloadSkillManifest(fs.readFileSync(file, 'utf8'), {
        assetFileName: fileName,
        minContentLength: 64 * 1024,
        runtimeImport: './offloaded-skill-manifest',
      });
      if (!result) return null;
      this.emitFile({ type: 'asset', fileName, source: result.asset });
      return result.code;
    },
  };
}

/** Release bundles must contain the pinned verification key; dev stays bootable without it. */
export function assertReleaseLicenseKey(mode: string, pem: string | undefined): void {
  if (mode !== 'production') return;
  try {
    if (!pem?.trim().startsWith('-----BEGIN PUBLIC KEY-----') || crypto.createPublicKey(pem).asymmetricKeyType !== 'ed25519') throw new Error();
  } catch { throw new Error('NEXUS_LICENSE_PUBKEY must contain a valid Ed25519 public key for release builds'); }
}

// Main process bundle. Native modules are marked external so they are required
// straight from node_modules (dev) / app.asar.unpacked (prod) instead of being
// pulled into the Rollup graph, which would break the .node binaries.
export default defineConfig({
  plugins: [offloadBundledSkillAssets(), {
    name: 'nexus:require-license-key',
    configResolved(config) {
      if (config.command === 'build') assertReleaseLicenseKey(config.mode, process.env.NEXUS_LICENSE_PUBKEY);
    },
  }],
  server: {
    // Runtime data, never source: worker worktrees under `.dev-user-data/`
    // are full repository checkouts inside the watch root. Without this the
    // dev server rebuilds (and restarts Electron) on every worker dispatch.
    watch: {
      ignored: ['**/.dev-user-data/**', '**/.vite/**', '**/.dev-electron/**'],
    },
  },
  // A chave publica de licenca e lida via process.env.NEXUS_LICENSE_PUBKEY em
  // src/main/license-access.ts. Um app EMPACOTADO (.dmg) nao recebe a
  // env do shell em runtime, entao assamos o valor no bundle do main aqui:
  // `npm run make` (ou `npm start`) com NEXUS_LICENSE_PUBKEY exportada embute a
  // chave literal. Release sem chave Ed25519 falha no plugin acima; dev sem
  // chave continua abrindo, com acesso bloqueado por verification-unavailable.
  define: {
    'process.env.NEXUS_LICENSE_PUBKEY': JSON.stringify(
      process.env.NEXUS_LICENSE_PUBKEY ?? '',
    ),
  },
  build: {
    rollupOptions: {
      output: {
        // Electron Forge/Packager loads this exact main-process filename.
        entryFileNames: 'main.js',
      },
      // uiohook-napi / onnxruntime-node are OPTIONAL native modules for voice
      // (PTT keyup + Silero VAD). They may not be installed; marking them external
      // keeps them out of the Rollup graph so the build never tries to resolve
      // them — a runtime require() in a try/catch handles their absence.
      external: [
        '@lydell/node-pty',
        'better-sqlite3',
        'uiohook-napi',
        'onnxruntime-node',
        // Emscripten resolves its sibling .wasm from the module __dirname.
        // Keep the package external so Rollup cannot detach JS from the asset.
        '@ennuicastr/webrtcaec3.js',
        // ssh2 + optional natives (cpu-features / sshcrypto). Loaded only via
        // createSsh2Transport() require(); bundling them breaks Linux package.
        'ssh2',
        'cpu-features',
      ],
    },
  },
  resolve: {
    // tslib must bypass its exports map: the node+import condition resolves to
    // modules/index.js, which destructures the CJS default export — rolldown's
    // interop leaves .default undefined (tslib.js sets __esModule), crashing the
    // packaged app at startup. All deps use named imports, so the pure-ESM build
    // is a drop-in.
    alias: {
      tslib: require.resolve('tslib/tslib.es6.mjs'),
    },
    mainFields: ['module', 'jsnext:main', 'jsnext'],
  },
});
